1	import { useState, useMemo } from "react";
2	import { useParams, useLocation, Link } from "wouter";
3	import { Layout } from "@/components/layout";
4	import { Button } from "@/components/ui/button";
5	import { Badge } from "@/components/ui/badge";
6	import { Skeleton } from "@/components/ui/skeleton";
7	import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
8	import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
9	import { DateCalendar } from "@/components/ui/date-calendar";
10	import { useUser, useClerk } from "@clerk/react";
11	import { useToast } from "@/hooks/use-toast";
12	import { useQueryClient, useQuery, useMutation, useInfiniteQuery } from "@tanstack/react-query";
13	import { customFetch } from "@workspace/api-client-react";
14	import { Phone, Mail, Euro, Clock, User, Video, MapPin, Building2, CalendarDays, Users, Sparkles, CreditCard, Loader2, AlertCircle, MessageCircle, Star, LayoutDashboard } from "lucide-react";
15	import { SportPill, getSportLabel } from "@/components/sport-icon";
16	import { BackButton } from "@/components/back-button";
17	import { centsToEuroString } from "@/lib/money";
18	import { useViewAsCoach } from "@/lib/view-as-coach";
19	import { useRole } from "@/lib/useRole";
20	
21	const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
22	const API = `${BASE}/api`;
23	
24	const SPORT_OPTIONS = ["tennis", "basketball", "padel", "football", "badminton", "squash", "table_tennis", "golf", "snooker", "bowling"];
25	interface Coach {
26	  id: number;
27	  userId: string;
28	  name: string;
29	  email: string;
30	  bio?: string;
31	  photoUrl?: string;
32	  videoUrl?: string;
33	  pricePerHour?: number;
34	  sports: string[];
35	  availabilityDescription?: string;
36	  phone?: string;
37	  experienceYears?: number;
38	  qualifications?: string[];
39	  sportsAudiences?: Array<{ sport: string; audiences: string[] }>;
40	  // Server-computed Stripe-readiness flag. False when the coach's
41	  // user_profile.stripeAccountStatus is not 'active'; UI must disable booking
42	  // CTAs and surface a "payments unavailable" affordance.
43	  isBookable?: boolean;
44	  // Denormalized review aggregate. averageRating is null when no reviews yet
45	  // (renders "Naujas" badge); otherwise a 1.00–5.00 numeric.
46	  averageRating?: number | null;
47	  reviewCount?: number;
48	}
49	
50	interface ReviewItem {
51	  id: number;
52	  rating: number;
53	  comment: string | null;
54	  reviewerName: string;
55	  coachReplyText: string | null;
56	  coachReplyCreatedAt: string | null;
57	  createdAt: string;
58	}
59	
60	interface ReviewsResponse {
61	  coachId: number;
62	  averageRating: number | null;
63	  reviewCount: number;
64	  items: ReviewItem[];
65	  limit: number;
66	  offset: number;
67	  hasMore: boolean;
68	}
69	
70	async function fetchCoach(id: string): Promise<Coach> {
71	  const r = await fetch(`${API}/coaches/${id}`);
72	  if (!r.ok) throw new Error("Coach not found");
73	  return r.json();
74	}
75	
76	async function fetchMyCoach(asCoachId?: number | null): Promise<Coach | null> {
77	  const url = asCoachId != null ? `${API}/coaches/me?asCoach=${asCoachId}` : `${API}/coaches/me`;
78	  const r = await fetch(url, { credentials: "include" });
79	  if (r.status === 404) return null;
80	  if (!r.ok) throw new Error("Failed to fetch coach profile");
81	  return r.json();
82	}
83	
84	interface CoachService {
85	  id: number;
86	  coachId: number;
87	  name: string;
88	  description: string | null;
89	  sport: string;
90	  courtId: number | null;
91	  durationMin: number;
92	  priceCents: number;
93	  maxParticipants: number;
94	  audienceLevel: string | null;
95	  isActive: boolean;
96	  sortOrder: number;
97	}
98	
99	const AUDIENCE_LT: Record<string, string> = {
100	  kids: "Vaikai",
101	  beginners: "Pradedantieji",
102	  advanced: "Pažengę",
103	  pros: "Profesionalai",
104	};
105	
106	function formatDuration(min: number): string {
107	  if (min < 60) return `${min} min`;
108	  const hours = min / 60;
109	  if (Number.isInteger(hours)) return `${hours} val.`;
110	  // 1.5 → "1,5 val." in Lithuanian locale convention
111	  return `${hours.toString().replace(".", ",")} val.`;
112	}
113	
114	// Format a Date as YYYY-MM-DD in local Europe/Vilnius time. We can't use
115	// toISOString() — that returns UTC, which is off by the local TZ offset.
116	function formatLocalYmd(d: Date): string {
117	  const y = d.getFullYear();
118	  const m = String(d.getMonth() + 1).padStart(2, "0");
119	  const dd = String(d.getDate()).padStart(2, "0");
120	  return `${y}-${m}-${dd}`;
121	}
122	
123	interface CoachFacilityGroup {
124	  facilityId: number | null;
125	  facilityName: string | null;
126	  city: string | null;
127	  address: string | null;
128	  courts: Array<{ id: number; name: string }>;
129	}
130	
131	interface CoachApplication {
132	  invitationId: number;
133	  courtId: number;
134	  courtName: string;
135	  facilityId: number | null;
136	  facilityName: string | null;
137	  status: string;
138	  initiatedBy: string;
139	  message: string | null;
140	  createdAt: string;
141	}
142	
143	interface FacilityOption {
144	  id: number;
145	  name: string;
146	  city?: string | null;
147	  address?: string | null;
148	}
149	
150	export default function CoachPage() {
151	  const { id } = useParams<{ id?: string }>();
152	  const { user, isSignedIn } = useUser();
153	  const { openSignIn } = useClerk();
154	  const [, setLocation] = useLocation();
155	  const { toast } = useToast();
156	  const { isAdmin } = useRole();
157	  const qc = useQueryClient();
158	
159	  const isOwnProfileRoute = !id || id === "me";
160	  const { asCoachId, asCoachName, enter: enterViewAs, exit: exitViewAs } = useViewAsCoach();
161	
162	  const { data: coach, isLoading } = useQuery<Coach | null>({
163	    queryKey: isOwnProfileRoute ? ["coach", "me", asCoachId] : ["coach", id],
164	    queryFn: isOwnProfileRoute ? () => fetchMyCoach(asCoachId) : () => fetchCoach(id!),
165	    enabled: isOwnProfileRoute ? !!isSignedIn : true,
166	    retry: false,
167	  });
168	
169	  const isOwn = isOwnProfileRoute || (coach?.userId && user?.id === coach.userId);
170	  const coachId = coach?.id;
171	
172	  // Public facilities the coach is approved at — visible on every profile view
173	  const facilitiesQ = useQuery<CoachFacilityGroup[]>({
174	    queryKey: ["coach-facilities", coachId],
175	    queryFn: () => fetch(`${API}/coaches/${coachId}/facilities`).then(r => r.json()),
176	    enabled: !!coachId,
177	  });
178	
179	  // Coach services (lesson types) — visible on every profile view. Non-owners
180	  // get only active services from the API; owners get the full list.
181	  const servicesQ = useQuery<CoachService[]>({
182	    queryKey: ["coach-services", coachId],
183	    queryFn: () => fetch(`${API}/coaches/${coachId}/services`, { credentials: "include" }).then(r => r.ok ? r.json() : []),
184	    enabled: !!coachId,
185	  });
186	
187	  // Public review feed, paginated. "Rodyti daugiau" appends the next page via
188	  // useInfiniteQuery; each page request returns hasMore so the button hides
189	  // when the last page lands.
190	  const REVIEWS_PAGE_SIZE = 10;
191	  const reviewsQ = useInfiniteQuery({
192	    queryKey: ["coach-reviews", coachId],
193	    initialPageParam: 1 as number,
194	    queryFn: async ({ pageParam }): Promise<ReviewsResponse> => {
195	      const r = await fetch(`${API}/coaches/${coachId}/reviews?page=${pageParam}&limit=${REVIEWS_PAGE_SIZE}`);
196	      if (!r.ok) {
197	        return {
198	          coachId: Number(coachId),
199	          averageRating: null,
200	          reviewCount: 0,
201	          items: [],
202	          limit: REVIEWS_PAGE_SIZE,
203	          offset: 0,
204	          hasMore: false,
205	        };
206	      }
207	      return r.json() as Promise<ReviewsResponse>;
208	    },
209	    getNextPageParam: (last, all) => (last.hasMore ? all.length + 1 : undefined),
210	    enabled: !!coachId,
211	  });
212	  const reviewPages: ReviewsResponse[] = reviewsQ.data?.pages ?? [];
213	  const reviewItems: ReviewItem[] = reviewPages.flatMap((p) => p.items);
214	  const reviewMeta: ReviewsResponse | null = reviewPages[0] ?? null;
215	
216	
217	  // Flatten the coach's approved court ids → friendly labels. Used by the
218	  // student-facing booking dialog for the court selector. Pulls from
219	  // facilitiesQ (same source the public "Treniruoja čia" panel uses).
220	  const approvedCourtOptions = useMemo(() => {
221	    const out: Array<{ id: number; label: string }> = [];
222	    for (const f of facilitiesQ.data ?? []) {
223	      for (const c of f.courts) {
224	        const facilityBit = f.facilityName ? ` · ${f.facilityName}` : "";
225	        out.push({ id: c.id, label: `${c.name}${facilityBit}` });
226	      }
227	    }
228	    return out;
229	  }, [facilitiesQ.data]);
230	
231	  // ─── Booking dialog (student-facing) ─────────────────────────────────────
232	  // Opens when a non-owner clicks "Užsakyti" on a service card. The dialog
233	  // collects (courtId, date, startTime), polls /coach-bookings/quote for a
234	  // server-priced breakdown, then on submit calls POST /coach-bookings →
235	  // POST /payments/create-checkout and redirects to Stripe.
236	  const [bookingService, setBookingService] = useState<CoachService | null>(null);
237	  const [bookingCourtId, setBookingCourtId] = useState<number | null>(null);
238	  const [bookingDate, setBookingDate] = useState<Date | null>(null);
239	  const [bookingStartTime, setBookingStartTime] = useState<string | null>(null);
240	  const [isProcessingCheckout, setIsProcessingCheckout] = useState(false);
241	  const [showDatePicker, setShowDatePicker] = useState(false);
242	
243	  // Reset selection whenever the dialog closes OR the user picks a different
244	  // service (so reopening always starts clean).
245	  function openBookingDialog(svc: CoachService) {
246	    setBookingService(svc);
247	    setBookingCourtId(svc.courtId ?? null);
248	    setBookingDate(null);
249	    setBookingStartTime(null);
250	    setShowDatePicker(false);
251	  }
252	  function closeBookingDialog() {
253	    if (isProcessingCheckout) return;
254	    setBookingService(null);
255	    setBookingCourtId(null);
256	    setBookingDate(null);
257	    setBookingStartTime(null);
258	    setShowDatePicker(false);
259	  }
260	
261	  // Available start-time pills for the picked date. Re-fetches when the
262	  // student picks a new date. The endpoint does NOT take courtId — for
263	  // floating services it only checks coach availability, so a slot can
264	  // still 409 on POST if the chosen court is double-booked. We rely on the
265	  // server's final overlap check (resolveCoachBookingWindow) to catch that.
266	  const bookingDateYmd = bookingDate ? formatLocalYmd(bookingDate) : null;
267	  const slotsQ = useQuery<{ slots: Array<{ start: string; end: string; label: string }> }>({
268	    queryKey: ["coach-service-slots", coachId, bookingService?.id, bookingDateYmd],
269	    queryFn: async () => {
270	      if (!coachId || !bookingService || !bookingDateYmd) {
271	        return { slots: [] };
272	      }
273	      const r = await fetch(
274	        `${API}/coaches/${coachId}/services/${bookingService.id}/slots?date=${bookingDateYmd}`,
275	      );
276	      if (!r.ok) return { slots: [] };
277	      return r.json();
278	    },
279	    enabled: !!coachId && !!bookingService && !!bookingDateYmd,
280	  });
281	
282	  // Live quote — fetched only when all three inputs are settled. A failed
283	  // quote (409 etc.) is surfaced as a banner instead of preventing display
284	  // of the other steps, so the user can adjust.
285	  const quoteEnabled = !!bookingService && !!bookingCourtId && !!bookingDateYmd && !!bookingStartTime;
286	  const quoteQ = useQuery<{
287	    courtId: number;
288	    startTime: string;
289	    endTime: string;
290	    durationMin: number;
291	    courtCents: number;
292	    serviceCents: number;
293	    totalCents: number;
294	  }>({
295	    queryKey: [
296	      "coach-booking-quote",
297	      bookingService?.id,
298	      bookingCourtId,
299	      bookingDateYmd,
300	      bookingStartTime,
301	    ],
302	    queryFn: async () => {
303	      const qs = new URLSearchParams({
304	        coachServiceId: String(bookingService!.id),
305	        date: bookingDateYmd!,
306	        startTime: bookingStartTime!,
307	      });
308	      if (bookingService!.courtId == null && bookingCourtId != null) {
309	        qs.set("courtId", String(bookingCourtId));
310	      }
311	      return await customFetch<{
312	        courtId: number;
313	        startTime: string;
314	        endTime: string;
315	        durationMin: number;
316	        courtCents: number;
317	        serviceCents: number;
318	        totalCents: number;
319	      }>(`${API}/coach-bookings/quote?${qs.toString()}`);
320	    },
321	    enabled: quoteEnabled,
322	    retry: false,
323	  });
324	
325	  // Court label lookup — used both in the RadioGroup and the summary line.
326	  // Falls back to the raw id if (somehow) the picked court isn't in the
327	  // coach's approved list anymore.
328	  function labelForCourt(id: number): string {
329	    return approvedCourtOptions.find(c => c.id === id)?.label ?? `Aikštelė #${id}`;
330	  }
331	
332	  async function submitCoachBooking() {
333	    if (!bookingService || !bookingCourtId || !bookingDateYmd || !bookingStartTime) {
334	      return;
335	    }
336	    if (!isSignedIn) {
337	      openSignIn();
338	      return;
339	    }
340	    setIsProcessingCheckout(true);
341	    try {
342	      // Step 1 — create the pending booking row.
343	      const created = await customFetch<{ bookingId: number }>(`${API}/coach-bookings`, {
344	        method: "POST",
345	        body: JSON.stringify({
346	          coachServiceId: bookingService.id,
347	          // Server ignores this when service.courtId is set, but we send it
348	          // anyway so floating services route through the same payload shape.
349	          courtId: bookingCourtId,
350	          date: bookingDateYmd,
351	          startTime: bookingStartTime,
352	        }),
353	      });
354	
355	      // Step 2 — kick off Stripe checkout with the same bookingId. The
356	      // server reads the prices it already snapshotted onto the booking
357	      // (Invariant B) so we don't need to re-send anything here.
358	      const origin = window.location.origin + BASE;
359	      const successUrl = `${origin}/booking-confirmed`;
360	      const cancelUrl = `${origin}/coach/${coach?.id ?? id ?? ""}`;
361	      const checkout = await customFetch<{ url: string }>(`${API}/payments/create-checkout`, {
362	        method: "POST",
363	        body: JSON.stringify({
364	          bookingId: created.bookingId,
365	          successUrl,
366	          cancelUrl,
367	        }),
368	      });
369	      window.location.href = checkout.url;
370	    } catch (e) {
371	      const msg = e instanceof Error ? e.message : "Nepavyko užbaigti užsakymo";
372	      toast({ title: "Klaida", description: msg, variant: "destructive" });
373	      setIsProcessingCheckout(false);
374	    }
375	  }
376	
377	  if (isOwnProfileRoute && !isSignedIn) {
378	    return (
379	      <Layout>
380	        <div className="container mx-auto px-4 py-20 text-center text-muted-foreground">
381	          Prisijunkite, kad matytumėte trenerio profilį.
382	        </div>
383	      </Layout>
384	    );
385	  }
386	
387	  if (isLoading) {
388	    return (
389	      <Layout>
390	        <div className="container mx-auto px-4 py-12 max-w-2xl space-y-6">
391	          <Skeleton className="h-40 w-full rounded-2xl" />
392	          <Skeleton className="h-60 w-full rounded-2xl" />
393	        </div>
394	      </Layout>
395	    );
396	  }
397	
398	  if (!coach && !isOwnProfileRoute) {
399	    return (
400	      <Layout>
401	        <div className="container mx-auto px-4 py-20 text-center">
402	          <h1 className="text-2xl font-bold mb-3">Treneris nerastas</h1>
403	          <Link href="/coaches">
404	            <Button variant="outline" className="mt-4">Grįžti į sąrašą</Button>
405	          </Link>
406	        </div>
407	      </Layout>
408	    );
409	  }
410	
411	  // /coach/me is now a pure read-only storefront preview. All editing lives
412	  // under the coach dashboard (/coach/dashboard and its sidebar tabs).
413	  const displayCoach = coach;
414	
415	  return (
416	    <Layout>
417	      {isOwnProfileRoute && asCoachName && (
418	        <div
419	          role="status"
420	          className="flex items-center gap-3 px-4 py-2 bg-amber-100 dark:bg-amber-900/40 border-b border-amber-300 dark:border-amber-700 text-amber-900 dark:text-amber-100"
421	        >
422	          <span className="text-sm flex-1 min-w-0 truncate">
423	            Žiūrite kaip treneris: <strong>{asCoachName}</strong> · tik skaitymo režimas
424	          </span>
425	          <button
426	            type="button"
427	            onClick={exitViewAs}
428	            className="text-xs font-semibold underline hover:no-underline shrink-0"
429	          >
430	            Išeiti
431	          </button>
432	        </div>
433	      )}
434	      {isOwn && !asCoachName && (
435	        <div
436	          role="status"
437	          className="sticky top-16 z-30 flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-3 px-4 py-3 bg-primary/10 border-b border-primary/30 text-foreground"
438	        >
439	          <span className="text-sm flex-1 min-w-0">
440	            <strong>Tai yra jūsų viešas profilis.</strong>{" "}
441	            <span className="text-muted-foreground">Visas valdymas perkeltas į Trenerio skydelį.</span>
442	          </span>
443	          <Button
444	            size="sm"
445	            onClick={() => setLocation("/coach/dashboard")}
446	            className="shrink-0 self-start sm:self-auto"
447	          >
448	            <LayoutDashboard className="w-4 h-4 mr-1.5" />
449	            Eiti į skydelį
450	          </Button>
451	        </div>
452	      )}
453	      <div className="container mx-auto px-4 py-12 max-w-2xl space-y-6">
454	
455	        {/* Back link */}
456	        <BackButton to="/coaches" label="Visi treneriai" />
457	
458	        {/* Header card */}
459	        <div className="bg-card border rounded-2xl p-6 shadow-sm">
460	          <div className="flex items-start justify-between gap-4">
461	            <div className="flex items-center gap-4">
462	              {displayCoach?.photoUrl ? (
463	                <img
464	                  src={displayCoach.photoUrl}
465	                  alt={displayCoach.name}
466	                  className="w-20 h-20 rounded-full object-cover border-2 border-primary/20 shrink-0"
467	                />
468	              ) : (
469	                <div className="w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
470	                  <User className="w-10 h-10 text-primary/60" />
471	                </div>
472	              )}
473	              <div>
474	                <h1 className="text-2xl font-bold">{displayCoach?.name ?? (isOwnProfileRoute ? "Trenerio profilis" : "")}</h1>
475	                {displayCoach?.email && (
476	                  <p className="text-sm text-muted-foreground flex items-center gap-1.5 mt-0.5">
477	                    <Mail className="w-3.5 h-3.5" />
478	                    {displayCoach.email}
479	                  </p>
480	                )}
481	                {displayCoach?.phone && (
482	                  <p className="text-sm text-muted-foreground flex items-center gap-1.5 mt-0.5">
483	                    <Phone className="w-3.5 h-3.5" />
484	                    {displayCoach.phone}
485	                  </p>
486	                )}
487	              </div>
488	            </div>
489	            {isAdmin && !isOwn && !isOwnProfileRoute && displayCoach && (
490	              <Button
491	                size="sm"
492	                variant="outline"
493	                onClick={() => {
494	                  enterViewAs(displayCoach.id, displayCoach.name);
495	                  setLocation("/coach/dashboard");
496	                }}
497	              >
498	                <User className="w-4 h-4 mr-1.5" />
499	                Žiūrėti kaip šis treneris
500	              </Button>
501	            )}
502	          </div>
503	
504	          {displayCoach && (
505	            <div className="mt-5 space-y-4">
506	              {displayCoach.sports.length > 0 && (
507	                <div className="flex flex-wrap gap-2">
508	                  {displayCoach.sports.map(s => (
509	                    <SportPill key={s} sport={s} variant="subtle" />
510	                  ))}
511	                </div>
512	              )}
513	
514	              {(() => {
515	                // Audience levels per sport. We only render sports whose
516	                // audience array is non-empty. Single-sport coaches get a flat
517	                // pill row; multi-sport coaches keep per-sport grouping so a
518	                // tennis-kids-only / badminton-all-levels split stays legible.
519	                const groups = (displayCoach.sportsAudiences ?? [])
520	                  .filter(s => s.audiences.length > 0);
521	                if (groups.length === 0) return null;
522	                const multiSport = groups.length > 1;
523	                return (
524	                  <div className="space-y-1.5">
525	                    <div className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
526	                      Lygis
527	                    </div>
528	                    <div className={multiSport ? "space-y-1.5" : ""}>
529	                      {groups.map(g => (
530	                        <div key={g.sport} className="flex flex-wrap items-center gap-2">
531	                          {multiSport && (
532	                            <span className="text-xs text-muted-foreground shrink-0">
533	                              {getSportLabel(g.sport)}:
534	                            </span>
535	                          )}
536	                          {g.audiences.map(a => (
537	                            <Badge
538	                              key={a}
539	                              variant="secondary"
540	                              className="text-xs font-medium"
541	                            >
542	                              {AUDIENCE_LT[a] ?? a}
543	                            </Badge>
544	                          ))}
545	                        </div>
546	                      ))}
547	                    </div>
548	                  </div>
549	                );
550	              })()}
551	
552	              <div className="flex flex-wrap gap-4 text-sm">
553	                {displayCoach.pricePerHour != null && (
554	                  <div className="flex items-center gap-1.5 text-foreground font-semibold">
555	                    <Euro className="w-4 h-4 text-primary" />
556	                    {centsToEuroString(displayCoach.pricePerHour)}€ / val
557	                  </div>
558	                )}
559	                {displayCoach.availabilityDescription && (
560	                  <div className="flex items-center gap-1.5 text-muted-foreground">
561	                    <Clock className="w-4 h-4" />
562	                    {displayCoach.availabilityDescription}
563	                  </div>
