166	// GET /coaches — marketplace list with optional filters.
167	//
168	// Query params (all optional):
169	//   courtId                — restrict to coaches affiliated with this court
170	//   sport                  — filter by primary sport (joined via coach_sports)
171	//   audiences              — comma-separated subset of kids|beginners|advanced|pros
172	//                            (matches any coach who teaches at least one)
173	//   travelPolicies         — comma-separated subset of any_court|affiliated_only
174	//   cancellationPolicies   — comma-separated subset of flexible|standard|strict
175	//   minPrice / maxPrice    — integer cents
176	//   city                   — match coaches with at least one approved court in city
177	//   date + startTime + endTime — require continuous availability across that window
178	//                                (Europe/Vilnius). All three must be supplied together.
179	//
180	// Always returns approved + accepting coaches. Each coach is enriched with
181	// `cities: string[]` from approved court affiliations and `sportsAudiences`
182	// from the junction table.
183	router.get("/coaches", async (req, res): Promise<void> => {
184	  const q = req.query;
185	  const courtId = q.courtId ? parseInt(q.courtId as string, 10) : null;
186	  const sportFilter = typeof q.sport === "string" && q.sport.trim() ? q.sport.trim() : null;
187	  const audiencesFilter = typeof q.audiences === "string" && q.audiences.trim()
188	    ? q.audiences.split(",").map((s) => s.trim()).filter(Boolean)
189	    : null;
190	  const travelFilter = typeof q.travelPolicies === "string" && q.travelPolicies.trim()
191	    ? q.travelPolicies.split(",").map((s) => s.trim()).filter(Boolean)
192	    : null;
193	  const cancelFilter = typeof q.cancellationPolicies === "string" && q.cancellationPolicies.trim()
194	    ? q.cancellationPolicies.split(",").map((s) => s.trim()).filter(Boolean)
195	    : null;
196	  const minPrice = q.minPrice ? Number(q.minPrice) : null;
197	  const maxPrice = q.maxPrice ? Number(q.maxPrice) : null;
198	  const cityFilter = typeof q.city === "string" && q.city.trim() ? q.city.trim() : null;
199	  const dateFilter = typeof q.date === "string" && /^\d{4}-\d{2}-\d{2}$/.test(q.date) ? q.date : null;
200	  const startTime = typeof q.startTime === "string" && /^\d{2}:\d{2}$/.test(q.startTime) ? q.startTime : null;
201	  const endTime = typeof q.endTime === "string" && /^\d{2}:\d{2}$/.test(q.endTime) ? q.endTime : null;
202	  const hasAvailabilityWindow = !!(dateFilter && startTime && endTime);
203	
204	  // Build base SQL filters on coachesTable.
205	  // The marketplace shield: every public listing requires the coach's
206	  // user_profile.stripeAccountStatus = 'active' so unbookable coaches never
207	  // surface to players. The join is enforced as INNER below; if Stripe flips
208	  // a coach back to pending/disabled, they disappear immediately on next read.
209	  const baseConditions = [
210	    eq(coachesTable.status, "approved"),
211	    eq(userProfilesTable.stripeAccountStatus, "active"),
212	  ];
213	  if (Number.isFinite(minPrice) && minPrice !== null) {
214	    baseConditions.push(sql`${coachesTable.pricePerHour} >= ${minPrice}`);
215	  }
216	  if (Number.isFinite(maxPrice) && maxPrice !== null) {
217	    baseConditions.push(sql`${coachesTable.pricePerHour} <= ${maxPrice}`);
218	  }
219	  if (travelFilter && travelFilter.length > 0) {
220	    baseConditions.push(inArray(coachesTable.travelPolicy, travelFilter));
221	  }
222	  if (cancelFilter && cancelFilter.length > 0) {
223	    baseConditions.push(inArray(coachesTable.cancellationPolicy, cancelFilter));
224	  }
225	
226	  let coaches: Array<typeof coachesTable.$inferSelect>;
227	  if (courtId !== null && !isNaN(courtId)) {
228	    const rows = await db
229	      .select({ coach: coachesTable })
230	      .from(courtCoachesTable)
231	      .innerJoin(coachesTable, eq(courtCoachesTable.coachId, coachesTable.id))
232	      .innerJoin(userProfilesTable, eq(userProfilesTable.userId, coachesTable.userId))
233	      .where(and(eq(courtCoachesTable.courtId, courtId), ...baseConditions));
234	    coaches = rows.map((r) => r.coach);
235	  } else {
236	    const rows = await db
237	      .select({ coach: coachesTable })
238	      .from(coachesTable)
239	      .innerJoin(userProfilesTable, eq(userProfilesTable.userId, coachesTable.userId))
240	      .where(and(...baseConditions))
241	      .orderBy(coachesTable.createdAt);
242	    coaches = rows.map((r) => r.coach);
243	  }
244	
245	  if (coaches.length === 0) { res.json([]); return; }
246	
247	  // City + audience filtering needs a junction-table join. Load both in one
248	  // pass for the candidate set; we already have the row identities.
249	  const ids = coaches.map((c) => c.id);
250	  const [affiliationRows, sportsRows] = await Promise.all([
251	    db.select({
252	      coachId: courtCoachesTable.coachId,
253	      facilityId: facilitiesTable.id,
254	      facilityName: facilitiesTable.name,
255	      facilityCity: facilitiesTable.city,
256	      facilityLat: facilitiesTable.latitude,
257	      facilityLng: facilitiesTable.longitude,
258	      courtSport: courtsTable.type,
259	    })
260	      .from(courtCoachesTable)
261	      .innerJoin(courtsTable, eq(courtCoachesTable.courtId, courtsTable.id))
262	      .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
263	      .where(inArray(courtCoachesTable.coachId, ids)),
264	    db.select({
265	      coachId: coachSportsTable.coachId,
266	      sport: coachSportsTable.sport,
267	      audiences: coachSportsTable.audiences,
268	    })
269	      .from(coachSportsTable)
270	      .where(inArray(coachSportsTable.coachId, ids)),
271	  ]);
272	
273	  const citiesByCoach = new Map<number, Set<string>>();
274	  // facilityAffiliations: one entry per (coach, facility). Multiple courts of
275	  // the same facility collapse into a single marker; their sports are merged.
276	  // Used by the marketplace map view; the list view ignores it.
277	  type FacilityAffiliation = {
278	    facilityId: number;
279	    facilityName: string;
280	    city: string | null;
281	    latitude: number;
282	    longitude: number;
283	    sports: string[];
284	  };
285	  const affiliationsByCoach = new Map<number, Map<number, FacilityAffiliation>>();
286	  for (const r of affiliationRows) {
287	    if (r.facilityCity) {
288	      if (!citiesByCoach.has(r.coachId)) citiesByCoach.set(r.coachId, new Set());
289	      citiesByCoach.get(r.coachId)!.add(r.facilityCity);
290	    }
291	    if (
292	      r.facilityId == null ||
293	      r.facilityLat == null ||
294	      r.facilityLng == null ||
295	      r.facilityName == null
296	    ) {
297	      continue;
298	    }
299	    let perCoach = affiliationsByCoach.get(r.coachId);
300	    if (!perCoach) {
301	      perCoach = new Map();
302	      affiliationsByCoach.set(r.coachId, perCoach);
303	    }
304	    const existing = perCoach.get(r.facilityId);
305	    if (existing) {
306	      if (r.courtSport && !existing.sports.includes(r.courtSport)) {
307	        existing.sports.push(r.courtSport);
308	      }
309	    } else {
310	      perCoach.set(r.facilityId, {
311	        facilityId: r.facilityId,
312	        facilityName: r.facilityName,
313	        city: r.facilityCity ?? null,
314	        latitude: r.facilityLat,
315	        longitude: r.facilityLng,
316	        sports: r.courtSport ? [r.courtSport] : [],
317	      });
318	    }
319	  }
320	
321	  const sportsByCoach = new Map<number, Array<{ sport: string; audiences: string[] }>>();
322	  for (const r of sportsRows) {
323	    if (!sportsByCoach.has(r.coachId)) sportsByCoach.set(r.coachId, []);
324	    sportsByCoach.get(r.coachId)!.push({ sport: r.sport, audiences: r.audiences });
325	  }
326	
327	  // Post-filter by sport, audiences, city. Done in app code so we can use the
328	  // already-loaded junction-table data; for tiny N (<100s of coaches) the cost
329	  // is negligible vs. building dynamic SQL with array overlap operators.
330	  let filtered = coaches.filter((c) => {
331	    const entries = sportsByCoach.get(c.id) ?? [];
332	    if (sportFilter) {
333	      const sportEntry = entries.find((e) => e.sport === sportFilter);
334	      if (!sportEntry) return false;
335	      if (audiencesFilter && audiencesFilter.length > 0) {
336	        const hit = audiencesFilter.some((a) => sportEntry.audiences.includes(a));
337	        if (!hit) return false;
338	      }
339	    } else if (audiencesFilter && audiencesFilter.length > 0) {
340	      // Without a sport filter, match if ANY sport the coach teaches has at
341	      // least one of the requested audiences.
342	      const anyHit = entries.some((e) => audiencesFilter.some((a) => e.audiences.includes(a)));
343	      if (!anyHit) return false;
344	    }
345	    if (cityFilter) {
346	      const cities = citiesByCoach.get(c.id);
347	      if (!cities || !cities.has(cityFilter)) return false;
348	    }
349	    return true;
350	  });
351	
352	  // Availability filter: continuous coverage across the requested window.
353	  // Computed last so we only run per-coach queries on the post-filtered set.
354	  if (hasAvailabilityWindow) {
355	    const startUtc = vilniusToUtc(dateFilter, startTime!).getTime();
356	    const endUtc = vilniusToUtc(dateFilter, endTime!).getTime();
357	    const STEP_MS = 30 * 60_000;
358	    if (endUtc > startUtc && (endUtc - startUtc) % STEP_MS === 0) {
359	      const availability = await Promise.all(filtered.map(async (c) => {
360	        const slots = await getCoachAvailability(c.id, dateFilter);
361	        const startSet = new Set(slots.map((s) => new Date(s.start).getTime()));
362	        for (let t = startUtc; t < endUtc; t += STEP_MS) {
363	          if (!startSet.has(t)) return { coach: c, available: false };
364	        }
365	        return { coach: c, available: true };
366	      }));
367	      filtered = availability.filter((a) => a.available).map((a) => a.coach);
368	    }
369	  }
370	
371	  // Stable sort: paid-promoted coaches float to the top, then the existing
372	  // default order (by review rating, with createdAt as a tiebreaker).
373	  const now = Date.now();
374	  const isCoachPromoted = (c: typeof coachesTable.$inferSelect): boolean =>
375	    c.promotedUntil != null && c.promotedUntil.getTime() > now;
376	  const ratingOf = (c: typeof coachesTable.$inferSelect): number =>
377	    c.averageRating != null ? Number(c.averageRating) : -1;
378	  filtered.sort((a, b) => {
379	    const pa = isCoachPromoted(a) ? 1 : 0;
380	    const pb = isCoachPromoted(b) ? 1 : 0;
381	    if (pa !== pb) return pb - pa;
382	    const ra = ratingOf(a);
383	    const rb = ratingOf(b);
384	    if (ra !== rb) return rb - ra;
385	    return a.createdAt.getTime() - b.createdAt.getTime();
386	  });
387	
388	  res.json(filtered.map((c) => ({
389	    ...formatPublicCoach(c),
390	    cities: Array.from(citiesByCoach.get(c.id) ?? []),
391	    sportsAudiences: sportsByCoach.get(c.id) ?? [],
392	    facilityAffiliations: Array.from(affiliationsByCoach.get(c.id)?.values() ?? []),
393	  })));
394	});
