450	// Only publicly-visible courts (status approved/active) and verified facilities are returned.
451	router.get("/coaches/:id/facilities", async (req, res, next): Promise<void> => {
452	  // Fall through when the path collides with /coaches/me/facilities — that
453	  // literal route is declared later in this file and is the one we want for
454	  // the signed-in coach's own affiliations. Returning 400 here would break
455	  // the Settings → Bendra "Aikštelės partnerystės" panel.
456	  if (req.params.id === "me") { next(); return; }
457	  const id = parseInt(String(req.params.id), 10);
458	  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
459	  const [coach] = await db.select().from(coachesTable)
460	    .where(and(eq(coachesTable.id, id), eq(coachesTable.status, "approved")));
461	  if (!coach) { res.json([]); return; }
462	
463	  const rows = await db
464	    .select({ court: courtsTable, facility: facilitiesTable })
465	    .from(courtCoachesTable)
466	    .innerJoin(courtsTable, eq(courtCoachesTable.courtId, courtsTable.id))
467	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
468	    .where(and(
469	      eq(courtCoachesTable.coachId, id),
470	      inArray(courtsTable.status, ["approved", "active"]),
471	      // If court is in a facility, that facility must be verified.
472	      // Standalone courts (no facility) pass this check via the OR.
473	      or(
474	        isNull(courtsTable.facilityId),
475	        eq(facilitiesTable.verificationStatus, "active"),
