1108	router.post("/owner/respond-to-coach", requireOwner, async (req, res): Promise<void> => {
1109	  const { invitationId, decision } = req.body ?? {};
1110	  const id = Number(invitationId);
1111	  if (!Number.isFinite(id)) { res.status(400).json({ error: "invitationId required" }); return; }
1112	  if (decision !== "approve" && decision !== "reject") {
1113	    res.status(400).json({ error: "decision must be 'approve' or 'reject'" }); return;
1114	  }
1115	
1116	  const [invite] = await db.select().from(courtCoachInvitationsTable)
1117	    .where(eq(courtCoachInvitationsTable.id, id));
1118	  if (!invite) { res.status(404).json({ error: "Invitation not found" }); return; }
1119	
1120	  const [court] = await db.select().from(courtsTable).where(eq(courtsTable.id, invite.courtId));
1121	  if (!court) { res.status(404).json({ error: "Court not found" }); return; }
1122	
1123	  const canEdit = await isOwner(req, await getCourtOwnerUserId(court.facilityId));
1124	  if (!canEdit) { res.status(403).json({ error: "Forbidden – not the court owner" }); return; }
1125	
1126	  if (invite.status !== "pending") {
1127	    res.status(409).json({ error: `Invitation already ${invite.status}` }); return;
1128	  }
1129	
1130	  await db.update(courtCoachInvitationsTable)
1131	    .set({ status: decision === "approve" ? "approved" : "rejected" })
1132	    .where(eq(courtCoachInvitationsTable.id, id));
1133	
1134	  if (decision === "approve" && invite.targetUserId) {
1135	    let [coach] = await db.select().from(coachesTable)
1136	      .where(eq(coachesTable.userId, invite.targetUserId));
1137	    if (!coach) {
1138	      [coach] = await db.insert(coachesTable).values({
1139	        userId: invite.targetUserId,
1140	        name: invite.targetName ?? "Treneris",
1141	        email: invite.targetEmail ?? "",
1142	        status: "approved",
1143	        sports: [],
1144	      }).returning();
1145	    }
1146	    const [existing] = await db.select().from(courtCoachesTable)
1147	      .where(and(eq(courtCoachesTable.courtId, court.id), eq(courtCoachesTable.coachId, coach.id)));
1148	    if (!existing) {
1149	      try {
1150	        await db.insert(courtCoachesTable).values({ courtId: court.id, coachId: coach.id });
1151	      } catch (err: unknown) {
1152	        // Postgres unique_violation (23505) — a concurrent approval already created the link.
1153	        // The end state (coach approved on this court) is what we want, so swallow and continue.
1154	        const code = (err as { code?: string } | null)?.code;
1155	        if (code !== "23505") throw err;
1156	      }
1157	    }
1158	    await sendNotification(invite.targetUserId, "court_coach_approved",
1159	      "Paraiška patvirtinta",
1160	      `Jūs priimtas kaip treneris į „${court.name}"`,
1161	      `/coach/me`,
1162	    ).catch(() => {});
1163	  } else if (decision === "reject" && invite.targetUserId) {
1164	    await sendNotification(invite.targetUserId, "court_coach_rejected",
1165	      "Paraiška atmesta",
1166	      `Jūsų paraiška „${court.name}" buvo atmesta`,
1167	      `/coach/me`,
1168	    ).catch(() => {});
1169	  }
1170	
1171	  res.json({ ok: true, status: decision === "approve" ? "approved" : "rejected" });
1172	});
